import re

WORDS = {'reference': 'довідник', 'dataset': 'датасет', 'tool': 'інструмент', 'as needed': 'за потреби', 'self-paced': 'у своєму темпі',
         '9 lessons': '9 уроків', 'dataset hub': 'збірка датасетів', 'textures, skies': 'текстури, небо', 'free GPU, weekly quota': 'GPU з тижневою квотою',
         'free GPU, with limits': 'GPU з лімітами', 'free developer plan': 'план для розробників', 'job board': 'вакансії', 'hub': 'кластер',
         'hackathons': 'хакатони', 'calendar': 'календар', 'hackathon': 'хакатон', 'community': 'спільнота', 'mentoring': 'менторство',
         'network': 'мережа', 'code': 'код', '3 courses': '3 курси', '3 h for chapter 2': '3 год на розділ 2'}

def hours(s):
    if s in WORDS:
        return WORDS[s]
    return re.sub(r'\bmin\b', 'хв', re.sub(r'\bh\b', 'год', s))

